import yaml,glob,collections
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f)); md=d.get('metadata') or {}
    rows[d['id']]=(d.get('status'),md.get('parent'))
kids=collections.defaultdict(list)
for k,(st,p) in rows.items():
    if p: kids[p].append(k)
OPEN={'active','pending','blocked'}
print("=== DONE parent with OPEN children ===")
for p,ks in sorted(kids.items()):
    if rows.get(p,('',''))[0]=='done':
        o=[k for k in ks if rows[k][0] in OPEN]
        if o: print(" ",p,"-> open:",o)
print("=== ALL children done but parent OPEN ===")
for p,ks in sorted(kids.items()):
    st=rows.get(p,('',''))[0]
    if st in OPEN and ks and all(rows[k][0]=='done' for k in ks):
        print(" ",p,f"({st}) all {len(ks)} children done")
EOF

